declare(strict_types=1);

use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Holder\SnippetVersionSubjectAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetVersionSubjectAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SnippetVersionSubjectAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSubject returns null on a freshly created holder.
     */
    public function testSubjectNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionSubjectAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSubjectAssigned());
        $this->assertNull($holder->getSubject());
    }
}
class ImplWithSnippetVersionSubjectAttributeHolderUnitTest
{
    use SnippetVersionSubjectAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSubjectRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSubject();
    }
}
